// ioBroker object: script.js.common.go-E_V4_Charger_Neu
// name: go-E_V4_Charger_Neu
// engineType: Blockly
// enabled: True

var datum, txt, TimeoutBezug, TimeoutPVPower, Calculation, TimeoutLess, TimeoutMore;

// Beschreibe diese Funktion …
async function Logfile(datum, txt) {
    if (getState('0_userdata.0.go-e_V4.DebugAktiv_V4').val) {
      require('fs').appendFileSync('/opt/iobroker/log/' + datum + ' - go_E_V4.log', formatDate(new Date(), "hh:mm:ss") + " \t" + txt + "\n");}
}


// ------->>>> Logfile

// LOG
schedule("* * * * *", async () => {
  // Zoe angesteckt ?
  if ((getState('renault.0.VF1AG000966808321.battery-status.batteryLevel').val < getState('0_userdata.0.go-e_V4.ZIEL_V4').val) && (getState('go-e.1.car').val == 1)) {
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Charger / Zoe ist nicht angesteckt');
  }
  // zu wenig PV Power
  if ((getState('alias.0.EM24 Hall Grid.PV_Überschuss').val < getState('0_userdata.0.go-e_V4.minPV_V4').val) && (getState('renault.0.VF1AG000966808321.battery-status.batteryLevel').val < getState('0_userdata.0.go-e_V4.ZIEL_V4').val) && (getState('go-e.1.car').val > 1) && (!getState('go-e.1.allow_charging').val)) {
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['Charger / keine Ladung - zu wenig PV (W): ',getState('alias.0.Fronius.AC-Power').val,', Überschuss (W): ',getState('alias.0.EM24 Hall Grid.PV_Überschuss').val].join(''));
  }
});
// VIS - Veränderungen
on({ id: '0_userdata.0.go-e_V4.maxA_3P_V4' /* maxAmpere_3P_V4 */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if (getState('go-e.1.ampere').val > (obj.state ? obj.state.val : '')) {
    setState('go-e.1.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, (obj.state ? obj.state.val : ''));
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'VIS / max 3P Ampere wurde geändert');
  }
});

// -------->>>> LADUNG - STOP
schedule("* * * * * *", async () => {
  if (getState('0_userdata.0.Victron.Grid_Halle_Überwachung').val) {
    if (getState('0_userdata.0.go-e_V4.LADUNG_V4').val || getState('0_userdata.0.go-e_V4.MinLadungAktiv_V4').val) {
      // GRID ÜBERWACHUNG
      setState('0_userdata.0.go-e_V4.LADUNG_V4' /* LADUNG_V4 */, false);
      setState('0_userdata.0.go-e_V4.MinLadungAktiv_V4' /* MinLadungAktiv_V4 */, false);
      setState('go-e.1.access_state' /* Access State (ast) */, 1);
      setState('go-e.1.allow_charging' /* Allow Charging (alw) */, 0);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Charger / GRID ÜBERWACHUNG---------------------------------');
    }
  } else if (getState('go-e.1.unlocked_by').val == 0) {
    if ((getState('0_userdata.0.go-e_V4.LADUNG_V4').val && getState('go-e.1.allow_charging').val) && (getState('alias.0.EM24 Hall Grid.Power').val >= 4000) && (!getState('0_userdata.0.go-e_V4.MinLadungAktiv_V4').val) && (!getState('0_userdata.0.go-e_V4.NOT_V4').val)) {
      // zu hoher Bezug
      setState('0_userdata.0.go-e_V4.LADUNG_V4' /* LADUNG_V4 */, false);
      setState('go-e.1.access_state' /* Access State (ast) */, 1);
      setState('go-e.1.allow_charging' /* Allow Charging (alw) */, 0);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Charger / Ladung gestoppt - zu viel Bezug ---------------------------------');
    } else if (!getState('0_userdata.0.go-e_V4.AUTO_V4').val && !getState('0_userdata.0.go-e_V4.NOT_V4').val && (getState('0_userdata.0.go-e_V4.LADUNG_V4').val || getState('go-e.1.car').val <= 1)) {
      // kein Modus aktiv
      setState('0_userdata.0.go-e_V4.LADUNG_V4' /* LADUNG_V4 */, false);
      setState('go-e.1.access_state' /* Access State (ast) */, 1);
      setState('go-e.1.allow_charging' /* Allow Charging (alw) */, 0);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Charger / Ladung gestoppt ---------------------------------');
    } else if (getState('renault.0.VF1AG000966808321.battery-status.batteryLevel').val >= getState('0_userdata.0.go-e_V4.ZIEL_V4').val && getState('0_userdata.0.go-e_V4.LADUNG_V4').val) {
      // Zielladung erreicht
      setState('0_userdata.0.go-e_V4.LADUNG_V4' /* LADUNG_V4 */, false);
      setState('go-e.1.access_state' /* Access State (ast) */, 1);
      setState('go-e.1.allow_charging' /* Allow Charging (alw) */, 0);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Charger / Ladung gestoppt - Zielladung erreicht -------------------------------');
    } else if (getState('go-e.1.car').val <= 1 && getState('0_userdata.0.go-e_V4.LADUNG_V4').val) {
      // kein Auto angesteckt
      setState('0_userdata.0.go-e_V4.LADUNG_V4' /* LADUNG_V4 */, false);
      setState('go-e.1.access_state' /* Access State (ast) */, 1);
      setState('go-e.1.allow_charging' /* Allow Charging (alw) */, 0);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Charger / Ladung gestoppt - kein Auto angehängt -------------------------------');
    } else if (getState('renault.0.VF1AG000966808321.battery-status.batteryLevel').val >= getState('0_userdata.0.go-e_V4.MinLadungProzent_V4').val && getState('0_userdata.0.go-e_V4.MinLadungAktiv_V4').val) {
      // MIN-Ladung fertig
      setState('0_userdata.0.go-e_V4.MinLadungAktiv_V4' /* MinLadungAktiv_V4 */, false);
      setState('go-e.1.access_state' /* Access State (ast) */, 1);
      setState('go-e.1.allow_charging' /* Allow Charging (alw) */, 0);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Charger / MIN Ladung beendet ---------------------------------');
    }
  }
});

// -------->>>> LADUNG - START
schedule("*/5 * * * * *", async () => {
  if ((getState('go-e.1.unlocked_by').val == 0) && (!getState('0_userdata.0.Victron.Grid_Halle_Überwachung').val)) {
    // -------->>>> MIN Ladung starten
    if (getState('0_userdata.0.go-e_V4.AUTO_V4').val && getState('0_userdata.0.go-e_V4.MinLadung_V4').val && (!getState('0_userdata.0.go-e_V4.NOT_V4').val) && (getState('renault.0.VF1AG000966808321.battery-status.batteryLevel').val < getState('0_userdata.0.go-e_V4.MinLadungProzent_V4').val) && (getState('go-e.1.car').val > 1) && ((!getState('0_userdata.0.go-e_V4.MinLadungAktiv_V4').val) || (!getState('0_userdata.0.go-e_V4.LADUNG_V4').val))) {
      setState('0_userdata.0.go-e_V4.LADUNG_V4' /* LADUNG_V4 */, true);
      setState('0_userdata.0.go-e_V4.MinLadungAktiv_V4' /* MinLadungAktiv_V4 */, true);
      setState('go-e.1.access_state' /* Access State (ast) */, 0);
      setState('go-e.1.allow_charging' /* Allow Charging (alw) */, 1);
      if (getState('0_userdata.0.go-e_V4.3P_V4').val) {
        setState('go-e.1.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, (Math.min(Math.max(getState('0_userdata.0.go-e_V4.NOT_Ampere_V4').val, getState('0_userdata.0.go-e_V4.minA_3P_V4').val), getState('0_userdata.0.go-e_V4.maxA_3P_V4').val)));
      } else {
        setState('go-e.1.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, (Math.min(Math.max(getState('0_userdata.0.go-e_V4.NOT_Ampere_V4').val, getState('0_userdata.0.go-e_V4.minA_1P_V4').val), getState('0_userdata.0.go-e_V4.maxA_1P_V4').val)));
      }
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Charger / MIN Ladung gestartet ---------------------------------');
    }
    // -------->>>> NOT Ladung starten
    if (getState('0_userdata.0.go-e_V4.NOT_V4').val && (getState('go-e.1.car').val > 1) && (!getState('0_userdata.0.go-e_V4.LADUNG_V4').val)) {
      setState('0_userdata.0.go-e_V4.LADUNG_V4' /* LADUNG_V4 */, true);
      setState('go-e.1.access_state' /* Access State (ast) */, 0);
      setState('go-e.1.allow_charging' /* Allow Charging (alw) */, 1);
      if (getState('0_userdata.0.go-e_V4.3P_V4').val) {
        setState('go-e.1.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, getState('0_userdata.0.go-e_V4.NOT_Ampere_V4').val);
      } else {
        setState('go-e.1.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, getState('0_userdata.0.go-e_V4.NOT_Ampere_V4').val);
      }
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Charger / NOT Ladung gestartet ---------------------------------');
    }
    // --------->>>>> AUTO LADUNG starten
    if (getState('0_userdata.0.go-e_V4.AUTO_V4').val && ((!getState('0_userdata.0.go-e_V4.MinLadung_V4').val) || (getState('alias.0.EM24 Hall Grid.PV_Überschuss').val > 1200)) && (!getState('0_userdata.0.go-e_V4.NOT_V4').val) && (getState('renault.0.VF1AG000966808321.battery-status.batteryLevel').val < getState('0_userdata.0.go-e_V4.ZIEL_V4').val) && (getState('go-e.1.car').val > 1) && (!getState('0_userdata.0.go-e_V4.LADUNG_V4').val)) {
      setState('0_userdata.0.go-e_V4.LADUNG_V4' /* LADUNG_V4 */, true);
      if (getState('0_userdata.0.go-e_V4.3P_V4').val) {
        setState('go-e.1.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, getState('0_userdata.0.go-e_V4.minA_3P_V4').val);
      } else {
        setState('go-e.1.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, getState('0_userdata.0.go-e_V4.minA_1P_V4').val);
      }
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Charger / AUTO Ladung aktiviert ---------------------------------');
    }
  }
});
// --- NOTLADUNG AKTIV
on({ id: '0_userdata.0.go-e_V4.NOT_Ampere_V4' /* NOT_Ampere_V4 */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if (getState('go-e.1.amperePV').val != getState('0_userdata.0.go-e_V4.NOT_Ampere_V4').val) {
    setState('go-e.1.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, getState('0_userdata.0.go-e_V4.NOT_Ampere_V4').val);
  }
});
on({ id: 'renault.0.VF1AG000966808321.battery-status.batteryLevel' /* batteryLevel */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if ((getState('renault.0.VF1AG000966808321.battery-status.batteryLevel').val >= getState('0_userdata.0.go-e_V4.ZIEL_V4').val) && getState('0_userdata.0.go-e_V4.NOT_V4').val) {
    setState('0_userdata.0.go-e_V4.NOT_V4' /* NOT_V4 */, false);
    setState('0_userdata.0.go-e_V4.AUTO_V4' /* AUTO_V4 */, true);
  }
});
on({ id: '0_userdata.0.go-e_V4.LADUNG_V4' /* LADUNG_V4 */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if ((!(obj.state ? obj.state.val : '')) && getState('0_userdata.0.go-e_V4.NOT_V4').val) {
    setState('0_userdata.0.go-e_V4.NOT_V4' /* NOT_V4 */, false);
    setState('0_userdata.0.go-e_V4.AUTO_V4' /* AUTO_V4 */, true);
  }
});

// --->> Auto Ladung - starten/stoppen - NEU
on({ id: 'alias.0.EM24 Hall Grid.Power' /* N/c0619ab4bea6/grid/41/Ac/Power */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if ((obj.state ? obj.state.val : '') <= getState('0_userdata.0.go-e_V4.maxBezug_V4').val) {
    (() => { if (TimeoutBezug) { clearTimeout(TimeoutBezug); TimeoutBezug = null; }})();
  } else if (((obj.oldState ? obj.oldState.val : '') <= getState('0_userdata.0.go-e_V4.maxBezug_V4').val) && getState('go-e.1.allow_charging').val && (!getState('0_userdata.0.go-e_V4.NOT_V4').val) && (!getState('0_userdata.0.go-e_V4.MinLadungAktiv_V4').val)) {
    TimeoutBezug = setTimeout(async () => {
      TimeoutBezug = null;
      // zu hoher Bezug - STOP
      setState('go-e.1.access_state' /* Access State (ast) */, 1);
      setState('go-e.1.allow_charging' /* Allow Charging (alw) */, 0);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['Charger / AUTO Ladung gestoppt, PowerFronius: ',getState('alias.0.Fronius.AC-Power').val,', akt. Power: ',getState('alias.0.EM24 Hall Grid.Power').val,', max. Bezug: ',getState('0_userdata.0.go-e_V4.maxBezug_V4').val].join(''));
    }, 10000);
  }
});
on({ id: 'alias.0.Fronius.AC-Power' /* Actual PV AC power */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if ((obj.state ? obj.state.val : '') >= 1100) {
    (() => { if (TimeoutPVPower) { clearTimeout(TimeoutPVPower); TimeoutPVPower = null; }})();
  } else if (((obj.oldState ? obj.oldState.val : '') >= 1100) && getState('go-e.1.allow_charging').val && (!getState('0_userdata.0.go-e_V4.NOT_V4').val) && (!getState('0_userdata.0.go-e_V4.MinLadungAktiv_V4').val)) {
    TimeoutPVPower = setTimeout(async () => {
      TimeoutPVPower = null;
      // kein Überschuss - STOP
      setState('go-e.1.access_state' /* Access State (ast) */, 1);
      setState('go-e.1.allow_charging' /* Allow Charging (alw) */, 0);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['Charger / AUTO Ladung gestoppt, PowerFronius: ',getState('alias.0.Fronius.AC-Power').val,', akt. Power: ',getState('alias.0.EM24 Hall Grid.Power').val,', max. Bezug: ',getState('0_userdata.0.go-e_V4.maxBezug_V4').val].join(''));
    }, 10000);
  }
});
// Überschuss vorhanden - START
schedule("* * * * * *", async () => {
  if (getState('0_userdata.0.go-e_V4.AUTO_V4').val && getState('0_userdata.0.go-e_V4.LADUNG_V4').val && (getState('go-e.1.unlocked_by').val == 0)) {
    if (getState('alias.0.EM24 Hall Grid.PV_Überschuss').val > getState('0_userdata.0.go-e_V4.minPV_V4').val && !getState('go-e.1.allow_charging').val) {
      setState('go-e.1.access_state' /* Access State (ast) */, 0);
      setState('go-e.1.allow_charging' /* Allow Charging (alw) */, 1);
      if (getState('0_userdata.0.go-e_V4.3P_V4').val) {
        setState('go-e.1.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, getState('0_userdata.0.go-e_V4.minA_3P_V4').val);
      } else {
        setState('go-e.1.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, getState('0_userdata.0.go-e_V4.minA_1P_V4').val);
      }
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Charger / AUTO Ladung gestartet');
    }
  }
});

// --->> Ladung steuern
schedule("* * * * * *", async () => {
  // --->> Ladung steuern - reduzieren
  if (getState('0_userdata.0.go-e_V4.AUTO_V4').val && getState('0_userdata.0.go-e_V4.LADUNG_V4').val && getState('go-e.1.allow_charging').val && (getState('go-e.1.unlocked_by').val == 0) && (getState('go-e.1.energy.power').val > 1) && (getState('alias.0.EM24 Hall Grid.PV_Überschuss').val == 0) && (!TimeoutLess)) {
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['Charger / ---- Steuer - Zyklus reduzieren beginnt ----',', go-E (kW): ',getState('go-e.1.energy.power').val,', EM24 (W): ',getState('alias.0.EM24 Hall Grid.Power').val,', min.PVÜberschuss (W): ',getState('0_userdata.0.go-e_V4.minPV_V4').val,', go-E (A): ',getState('go-e.1.amperePV').val,', Fronius (W): ',getState('alias.0.Fronius.AC-Power').val].join(''));
    // aktueller Zählerwert
    Calculation = getState('alias.0.EM24 Hall Grid.Power').val * -1;
    // 1P/3P - Offset und berechne den Stromwert
    if (getState('0_userdata.0.go-e_V4.3P_V4').val) {
      Calculation = Calculation - 230;
      Calculation = Calculation / 230;
      Calculation = Calculation / 3;
    } else {
      Calculation = Calculation - 115;
      Calculation = Calculation / 230;
    }
    Calculation = Math.round(Calculation * 100) / 100;
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Charger / vorhandene Leistung pro Phase (W): ' + String(Calculation));
    Calculation = Math.round(Calculation - 0.51);
    Calculation = Calculation + getState('go-e.1.amperePV').val;
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Charger / neue Ampere pro Phase (A): ' + String(Calculation));
    if (Calculation > getState('go-e.1.amperePV').val + 1) {
      Calculation = getState('go-e.1.amperePV').val + 1;
    }
    if (getState('0_userdata.0.go-e_V4.3P_V4').val) {
      Calculation = Math.min(Math.max(Calculation, getState('0_userdata.0.go-e_V4.minA_3P_V4').val), getState('0_userdata.0.go-e_V4.maxA_3P_V4').val);
    } else {
      Calculation = Math.min(Math.max(Calculation, getState('0_userdata.0.go-e_V4.minA_1P_V4').val), getState('0_userdata.0.go-e_V4.maxA_1P_V4').val);
    }
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Charger / begrenzte Ampere pro Phase (A): ' + String(Calculation));
    if (getState('0_userdata.0.go-e_V4.MinLadungAktiv_V4').val) {
      if (getState('0_userdata.0.go-e_V4.NOT_Ampere_V4').val != getState('go-e.1.amperePV').val) {
        setState('go-e.1.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, getState('0_userdata.0.go-e_V4.NOT_Ampere_V4').val);
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Charger / -------->>>>> neuer Ladestrom MIN-Ladung(A): ' + String(getState('0_userdata.0.go-e_V4.NOT_Ampere_V4').val));
      }
    } else if (Calculation < getState('go-e.1.amperePV').val) {
      setState('go-e.1.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, Calculation);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Charger / -------->>>>> neuer Ladestrom (A): ' + String(Calculation));
      TimeoutLess = setTimeout(async () => {
        TimeoutLess = null;
      }, 2000);
    }
  }
  // --->> Ladung steuern - erhöhen
  if (getState('0_userdata.0.go-e_V4.AUTO_V4').val && getState('0_userdata.0.go-e_V4.LADUNG_V4').val && getState('go-e.1.allow_charging').val && (getState('go-e.1.unlocked_by').val == 0) && (getState('go-e.1.energy.power').val > 1) && (getState('alias.0.EM24 Hall Grid.PV_Überschuss').val > 0) && (!TimeoutMore)) {
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['Charger / ---- Steuer - Zyklus erhöhen beginnt ----',', go-E (kW): ',getState('go-e.1.energy.power').val,', EM24 (W): ',getState('alias.0.EM24 Hall Grid.Power').val,', min.PVÜberschuss (W): ',getState('0_userdata.0.go-e_V4.minPV_V4').val,', go-E (A): ',getState('go-e.1.amperePV').val,', Fronius (W): ',getState('alias.0.Fronius.AC-Power').val].join(''));
    // aktueller Zählerwert
    Calculation = getState('alias.0.EM24 Hall Grid.Power').val * -1;
    // 1P/3P - Offset und berechne den Stromwert
    if (getState('0_userdata.0.go-e_V4.3P_V4').val) {
      Calculation = Calculation - 230;
      Calculation = Calculation / 230;
      Calculation = Calculation / 3;
    } else {
      Calculation = Calculation - 115;
      Calculation = Calculation / 230;
    }
    Calculation = Math.round(Calculation * 100) / 100;
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Charger / vorhandene Leistung pro Phase (W): ' + String(Calculation));
    Calculation = Math.round(Calculation - 0.51);
    Calculation = Calculation + getState('go-e.1.amperePV').val;
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Charger / neue Ampere pro Phase (A): ' + String(Calculation));
    if (Calculation > getState('go-e.1.amperePV').val + 1) {
      Calculation = getState('go-e.1.amperePV').val + 1;
    }
    if (getState('0_userdata.0.go-e_V4.3P_V4').val) {
      Calculation = Math.min(Math.max(Calculation, getState('0_userdata.0.go-e_V4.minA_3P_V4').val), getState('0_userdata.0.go-e_V4.maxA_3P_V4').val);
    } else {
      Calculation = Math.min(Math.max(Calculation, getState('0_userdata.0.go-e_V4.minA_1P_V4').val), getState('0_userdata.0.go-e_V4.maxA_1P_V4').val);
    }
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Charger / begrenzte Ampere pro Phase (A): ' + String(Calculation));
    if (Calculation > getState('go-e.1.amperePV').val) {
      setState('go-e.1.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, Calculation);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Charger / -------->>>>> neuer Ladestrom (A): ' + String(Calculation));
      TimeoutMore = setTimeout(async () => {
        TimeoutMore = null;
      }, 10000);
    }
  }
});

false && false;


